import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:uuid/uuid.dart';\nimport '../../schedule/models/schedule.dart';\nimport '../../schedule/providers/schedule_providers.dart';\nimport '../../homework/providers/homework_providers.dart';\nimport '../../../core/providers/core_providers.dart';\n\nclass ManageScheduleScreen extends ConsumerStatefulWidget {\n  const ManageScheduleScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<ManageScheduleScreen> createState() => _ManageScheduleScreenState();\n}\n\nclass _ManageScheduleScreenState extends ConsumerState<ManageScheduleScreen> {\n  String? _selectedClassId;\n  bool _isLoading = false;\n\n  final List<String> _days = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس'];\n  final Map<String, List<TextEditingController>> _controllers = {};\n\n  @override\n  void initState() {\n    super.initState();\n    for (var day in _days) {\n      _controllers[day] = List.generate(6, (index) => TextEditingController()); // 6 lessons max\n    }\n  }\n\n  @override\n  void dispose() {\n    for (var list in _controllers.values) {\n      for (var c in list) {\n        c.dispose();\n      }\n    }\n    super.dispose();\n  }\n\n  void _loadExistingSchedule(Schedule? schedule) {\n    // Clear first\n    for (var day in _days) {\n      for (var i = 0; i < 6; i++) {\n        _controllers[day]![i].text = '';\n      }\n    }\n    if (schedule != null) {\n      schedule.scheduleData.forEach((day, lessonsDynamic) {\n        if (_controllers.containsKey(day)) {\n          List<dynamic> lessons = lessonsDynamic as List<dynamic>;\n          for (var i = 0; i < lessons.length && i < 6; i++) {\n            _controllers[day]![i].text = lessons[i].toString();\n          }\n        }\n      });\n    }\n  }\n\n  Future<void> _save() async {\n    if (_selectedClassId == null) {\n      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('يرجى اختيار الصف أولاً')));\n      return;\n    }\n\n    setState(() => _isLoading = true);\n    try {\n      Map<String, List<String>> scheduleData = {};\n      \n      for (var day in _days) {\n        List<String> dailyLessons = [];\n        for (var c in _controllers[day]!) {\n          if (c.text.trim().isNotEmpty) {\n            dailyLessons.add(c.text.trim());\n          }\n        }\n        if (dailyLessons.isNotEmpty) {\n          scheduleData[day] = dailyLessons;\n        }\n      }\n\n      final newSchedule = Schedule(\n        id: const Uuid().v4(),\n        classId: _selectedClassId!,\n        scheduleData: scheduleData,\n      );\n\n      await ref.read(scheduleServiceProvider).updateSchedule(newSchedule);\n      \n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('تم حفظ الجدول بنجاح')));\n      Navigator.pop(context);\n\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('خطأ: $e'), backgroundColor: Colors.red));\n    } finally {\n      if (mounted) setState(() => _isLoading = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final schoolId = 'dummy_school_id';\n    final classesAsync = ref.watch(classesProvider(schoolId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('إدارة جدول الحصص'),\n        actions: [\n          if (_selectedClassId != null)\n            IconButton(icon: const Icon(Icons.save), onPressed: _isLoading ? null : _save)\n        ],\n      ),\n      body: Column(\n        children: [\n          Padding(\n            padding: const EdgeInsets.all(16.0),\n            child: classesAsync.when(\n              data: (classes) {\n                return DropdownButtonFormField<String>(\n                  decoration: const InputDecoration(labelText: 'اختر الصف لتعديل جدوله', border: OutlineInputBorder()),\n                  value: _selectedClassId,\n                  items: classes.map((c) => DropdownMenuItem(value: c.id, child: Text(c.name))).toList(),\n                  onChanged: (val) {\n                    setState(() => _selectedClassId = val);\n                  },\n                );\n              },\n              loading: () => const LinearProgressIndicator(),\n              error: (e, _) => Text('خطأ: $e'),\n            ),\n          ),\n          \n          if (_selectedClassId != null)\n            Expanded(\n              child: Consumer(\n                builder: (context, ref, child) {\n                  final scheduleAsync = ref.watch(scheduleProvider(_selectedClassId!));\n                  \n                  return scheduleAsync.when(\n                    data: (schedule) {\n                      // Using Future.microtask to avoid building phase state changes\n                      Future.microtask(() => _loadExistingSchedule(schedule));\n                      \n                      return ListView.builder(\n                        padding: const EdgeInsets.all(16),\n                        itemCount: _days.length,\n                        itemBuilder: (context, index) {\n                          final day = _days[index];\n                          return Card(\n                            margin: const EdgeInsets.only(bottom: 16),\n                            child: ExpansionTile(\n                              title: Text(day, style: const TextStyle(fontWeight: FontWeight.bold)),\n                              children: List.generate(6, (lessonIndex) {\n                                return Padding(\n                                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n                                  child: TextField(\n                                    controller: _controllers[day]![lessonIndex],\n                                    decoration: InputDecoration(\n                                      labelText: 'الحصة ${lessonIndex + 1}',\n                                      border: const OutlineInputBorder(),\n                                      isDense: true,\n                                    ),\n                                  ),\n                                );\n                              }),\n                            ),\n                          );\n                        },\n                      );\n                    },\n                    loading: () => const Center(child: CircularProgressIndicator()),\n                    error: (e, _) => Center(child: Text('خطأ: $e')),\n                  );\n                },\n              ),\n            )\n          else\n            const Expanded(child: Center(child: Text('الرجاء اختيار الصف أولاً')))\n        ],\n      ),\n    );\n  }\n}\n